from __future__ import annotations
import itertools
import heapq
from typing import List, Mapping, Optional, Sequence, Tuple

def _sp(adj, src, dst):
    if src not in adj or dst not in adj:
        raise KeyError(src if src not in adj else dst)
    if src == dst:
        return (0, [src])
    dist = {n: float('inf') for n in adj}
    hops = {n: float('inf') for n in adj}
    pred = {n: None for n in adj}
    dist[src], hops[src] = 0, 0
    pq = [(0, 0, src)]
    while pq:
        d, h, u = heapq.heappop(pq)
        if d > dist[u] or (d == dist[u] and h > hops[u]):
            continue
        if u == dst:
            break
        for v, w in sorted(adj[u].items()):
            nd, nh = d + w, h + 1
            if nd < dist[v] or (nd == dist[v] and nh < hops[v]):
                dist[v], hops[v] = nd, nh
                pred[v] = u
                heapq.heappush(pq, (nd, nh, v))
    if dist[dst] == float('inf'):
        return None
    path = []
    cur = dst
    while cur:
        path.append(cur)
        cur = pred[cur]
    return (int(dist[dst]), path[::-1])

def plan_drop_route(adj, origin, destination, drops):
    if len(drops) != len(set(drops)):
        raise ValueError("drops contains duplicates")
    if len(drops) > 6:
        raise ValueError("drops contains more than 6 depots")
    for node in [origin, destination] + list(drops):
        if node not in adj:
            raise KeyError(node)
    if not drops:
        return _sp(adj, origin, destination)
    best = None
    for perm in sorted(itertools.permutations(drops)):
        cost, path = 0, [origin]
        cur = origin
        ok = True
        for nxt in list(perm) + [destination]:
            seg = _sp(adj, cur, nxt)
            if seg is None:
                ok = False
                break
            c, p = seg
            cost += c
            path.extend(p[1:])
            cur = nxt
        if ok:
            if best is None or cost < best[0] or (cost == best[0] and len(path) < len(best[1])):
                best = (cost, path)
    return best

